-- Curadoria das prateleiras: filmes e séries novos (13/10/2026).
--
-- Curadoria de 13/10/2026: obras com nota do TMDB acima de 6,5 que já
-- estavam no banco do site (a maioria vinda das bibliotecas dos bots) e
-- obras de listas de referência (cânones, premiações, cinema brasileiro,
-- animes, séries), revisadas uma a uma por oráculo. Ver o doc "Curadoria
-- de filmes" do projeto (claude/curadoria-de-filmes.md).
--
-- Regras:
--   • oráculo pela regra de sempre — filmes: Bogart 2000+ com 500+ votos,
--     Fincher até 1999 com 200+, Cypher o resto; séries: Bogart 2000+ com
--     300+, Fincher até 1999 com 100+, Cypher o resto e todo anime em
--     série;
--   • nota do TMDB acima de 6,5;
--   • filmes com 75+ votos e 60+ minutos; séries com 40+ votos;
--   • sem documentários (salvo exceções), stand-up, shows filmados,
--     compilações e curtas;
--   • lançamentos que ainda não assentaram (menos de 60 dias, ou Cypher
--     com menos de 180) ficaram de fora e foram para a lista de pesca
--     (public.pesca, migração 20261014010000).
--
-- São 2.604 títulos: 2.133 filmes e 471 séries; 1.571 vindos do
-- banco ('banco') e 1.033 das listas de referência ('listas').
--
--   Filmes (2.133)    banco  listas   total
--     Bogart            590     125     715
--     Fincher           431     395     826
--     Cypher            300     292     592
--     total           1.321     812   2.133
--
--   Séries (471)      banco  listas   total
--     Bogart            126      60     186
--     Fincher            14      16      30
--     Cypher            110     145     255
--     total             250     221     471
--
-- Só acrescenta: cada título vai para o fim do movie_ids (filme) ou do
-- tv_ids (série) da sua prateleira, e só se ainda não estiver em nenhuma
-- prateleira (pode rodar de novo sem duplicar). Dentro de cada prateleira,
-- os novos entram na ordem de mais votos. Os gatilhos de
-- recommendation_pools atualizam updated_at e a linha random-surprise de
-- cada oráculo (a união dos 9 humores, só de filmes).
--
-- Antes, uma cópia das personas fica em curation.persona_before_1013; no
-- fim, as personas de todos são recalculadas (quem já avaliou alguma
-- dessas obras pode mudar de código).
--
-- A lista fica em curation.shelf_additions_1013. A coluna nota_curadoria
-- (a justificativa de cada título) não vai neste arquivo: está só no banco.
--
-- Aplicada em 13–14/10/2026: as prateleiras foram de 3.062 para 5.195
-- filmes e de 823 para 1.294 séries.

-- A lista (uma linha por título; nota_curadoria fica de fora).
create table if not exists curation.shelf_additions_1013 (
  tmdb_id        integer not null,
  media_type     text    not null,
  card_type      text    not null,
  mood_key       text    not null,
  origem         text    not null,
  titulo         text,
  ano            integer,
  nota           numeric,
  votos          integer,
  nota_curadoria text,
  primary key (tmdb_id, media_type)
);

