-- Aplicação: cópia das personas, títulos no fim das prateleiras e
-- personas recalculadas.
create table if not exists curation.persona_before_1013 as
select id, personalidade_completa, persona_scores, persona_counted, now() saved_at from public.profiles;

with sel as (
  select a.*, row_number() over (partition by a.card_type, a.mood_key, a.media_type order by a.votos desc nulls last, a.tmdb_id) ord
  from curation.shelf_additions_1013 a
),
livres as (
  select s.* from sel s
  where not exists (
    select 1 from public.recommendation_pools rp
    where rp.mood_key <> 'random-surprise'
      and (case when s.media_type = 'movie' then rp.movie_ids else coalesce(rp.tv_ids, '[]'::jsonb) end) @> to_jsonb(s.tmdb_id))
),
novos as (
  select card_type, mood_key,
         coalesce(jsonb_agg(to_jsonb(tmdb_id) order by ord) filter (where media_type = 'movie'), '[]'::jsonb) movies,
         coalesce(jsonb_agg(to_jsonb(tmdb_id) order by ord) filter (where media_type = 'tv'), '[]'::jsonb) series
  from livres group by card_type, mood_key
)
update public.recommendation_pools rp
   set movie_ids = rp.movie_ids || n.movies,
       tv_ids = coalesce(rp.tv_ids, '[]'::jsonb) || n.series
  from novos n
 where rp.card_type = n.card_type and rp.mood_key = n.mood_key;

select count(public.refresh_user_persona(id)) from public.profiles;
